import io,itertools
from werkzeug.formparser import MultiPartParser
boundary=b'BOUNDARY'
h=b'--'+boundary+b'\r\nContent-Disposition: form-data; name="upload"; filename="x.bin"\r\nContent-Type: application/octet-stream\r\n\r\n'
t=b'\r\n--'+boundary+b'--\r\n'
class Stream:
 def __init__(self,chunks): self.chunks=iter(chunks)
 def read(self,n): return next(self.chunks,b'')
fail=[]; count=0
for n in range(5):
 for x in itertools.product([b'a',b'\r',b'\n'],repeat=n):
  p=b''.join(x); body=h+p+t
  for cut in range(len(h),len(body)):
   if cut==0: continue
   count+=1
   try:
    _,f=MultiPartParser().parse(Stream([body[:cut],body[cut:]]),boundary,len(body))
    got=f['upload'].read()
    if got!=p: fail.append((repr(p),cut-len(h),repr(got)))
   except Exception as e: fail.append((repr(p),cut-len(h),type(e).__name__+': '+str(e)))
print('cases',count,'failures',len(fail)); print('first failures',fail[:15])
for n in [65534,65535,65536,65537,65538]:
 p=b'\0'*n; body=h+p+t
 try:
  _,f=MultiPartParser().parse(io.BytesIO(body),boundary,len(body)); got=f['upload'].read();print(n,len(got),got==p)
 except Exception as e:print(n,repr(e))

